package com.company.orderapproval.customer.location.controller;
import com.company.orderapproval.common.response.*; import com.company.orderapproval.customer.location.dto.*; import com.company.orderapproval.customer.location.entity.BusinessCustomerLocationStatus; import com.company.orderapproval.customer.location.service.BusinessCustomerLocationService; import jakarta.servlet.http.HttpServletRequest; import jakarta.validation.Valid; import org.springframework.data.domain.*; import org.springframework.data.web.PageableDefault; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/business-customer-locations") public class BusinessCustomerLocationController {private final BusinessCustomerLocationService service;public BusinessCustomerLocationController(BusinessCustomerLocationService service){this.service=service;}
 @GetMapping @PreAuthorize("hasAuthority('CUSTOMER_VIEW')") public ResponseEntity<ApiResponse<PageResponse<BusinessCustomerLocationResponse>>> list(@RequestParam UUID businessCustomerId,@RequestParam(required=false) String search,@RequestParam(required=false) BusinessCustomerLocationStatus status,@PageableDefault(size=20,sort="createdAt",direction=Sort.Direction.DESC) Pageable p){return ResponseEntity.ok(ApiResponse.success("Business customer locations fetched successfully",PageResponse.from(service.list(businessCustomerId,search,status,p))));}
 @GetMapping("/{id}") @PreAuthorize("hasAuthority('CUSTOMER_VIEW')") public ResponseEntity<ApiResponse<BusinessCustomerLocationResponse>> get(@PathVariable UUID id){return ResponseEntity.ok(ApiResponse.success("Location fetched successfully",service.get(id)));}
 @PostMapping @PreAuthorize("hasAuthority('CUSTOMER_CREATE')") public ResponseEntity<ApiResponse<BusinessCustomerLocationResponse>> create(@RequestParam UUID businessCustomerId,@Valid @RequestBody CreateBusinessCustomerLocationRequest r,HttpServletRequest h){return ResponseEntity.status(HttpStatus.CREATED).body(ApiResponse.success("Location created successfully",service.create(businessCustomerId,r,h)));}
 @PutMapping("/{id}") @PreAuthorize("hasAuthority('CUSTOMER_UPDATE')") public ResponseEntity<ApiResponse<BusinessCustomerLocationResponse>> update(@PathVariable UUID id,@Valid @RequestBody UpdateBusinessCustomerLocationRequest r,HttpServletRequest h){return ResponseEntity.ok(ApiResponse.success("Location updated successfully",service.update(id,r,h)));}
}
